const { registrants, participants } = input;

// Create maps for quick registrant lookup
const registrantById = new Map();
const registrantByEmail = new Map();

registrants.forEach(reg => {
    registrantById.set(reg.id, reg);
    registrantByEmail.set(reg.email.toLowerCase(), reg);
});

// Track which registrants participated
const participatedRegistrantIds = new Set();

// Aggregate participants - group by registrant_id or email
const aggregated = new Map();

participants.forEach(p => {
    // Find matching registrant
    let registrant = null;

    if (p.registrant_id && registrantById.has(p.registrant_id)) {
        registrant = registrantById.get(p.registrant_id);
        participatedRegistrantIds.add(p.registrant_id);
    } else if (p.user_email) {
        registrant = registrantByEmail.get(p.user_email.toLowerCase());
        if (registrant) {
            participatedRegistrantIds.add(registrant.id);
        }
    }

    // Use registrant_id as key, fallback to email
    const key = p.registrant_id || p.user_email?.toLowerCase() || p.id;

    if (aggregated.has(key)) {
        const existing = aggregated.get(key);
        existing.total_duration += p.duration || 0;

        if (new Date(p.join_time) < new Date(existing.first_join_time)) {
            existing.first_join_time = p.join_time;
        }

        if (new Date(p.leave_time) > new Date(existing.last_leave_time)) {
            existing.last_leave_time = p.leave_time;
        }

        existing.session_count += 1;
    } else {
        aggregated.set(key, {
            total_duration: p.duration || 0,
            first_join_time: p.join_time,
            last_leave_time: p.leave_time,
            session_count: 1,
            participant: p,
            registrant: registrant
        });
    }
});

// Helper function to build merged object
const buildResult = (registrant, participantData) => {
    const participant = participantData?.participant;
    const hadParticipated = !!participantData;

    // Parse name from participant if available
    const nameParts = (participant?.name || '').split(' ');
    const firstNameFromParticipant = nameParts[0] || '';
    const lastNameFromParticipant = nameParts.slice(1).join(' ') || '';

    // Flatten custom questions
    const customQuestionsFlat = {};
    if (registrant?.custom_questions && Array.isArray(registrant.custom_questions)) {
        registrant.custom_questions.forEach((q, index) => {
            const questionKey = q.title || q.question || `question_${index + 1}`;
            customQuestionsFlat[questionKey] = q.value || q.answer || '';
        });
    }

    return {
        // Core identifiers
        email: registrant?.email || participant?.user_email || '',
        phone: registrant?.phone || '',

        // Name
        first_name: registrant?.first_name || firstNameFromParticipant,
        last_name: registrant?.last_name || lastNameFromParticipant,
        full_name: participant?.name || `${registrant?.first_name || ''} ${registrant?.last_name || ''}`.trim(),

        // Attendance metrics
        total_duration_seconds: participantData?.total_duration || 0,
        total_duration_minutes: Math.round((participantData?.total_duration || 0) / 60 * 100) / 100,
        first_join_time: participantData?.first_join_time || null,
        last_leave_time: participantData?.last_leave_time || null,
        session_count: participantData?.session_count || 0,

        // Registration details
        address: registrant?.address || '',
        city: registrant?.city || '',
        country: registrant?.country || '',
        zip: registrant?.zip || '',
        state: registrant?.state || '',
        industry: registrant?.industry || '',
        organization: registrant?.org || '',
        job_title: registrant?.job_title || '',
        comments: registrant?.comments || '',

        // Custom questions
        custom_questions: registrant?.custom_questions || [],
        ...customQuestionsFlat,

        // Status info
        registration_status: registrant?.status || '',
        registration_time: registrant?.create_time || '',

        // IDs
        registrant_id: participant?.registrant_id || registrant?.id || '',
        participant_id: participant?.id || '',
        user_id: participant?.user_id || '',

        // Flags
        internal_user: participant?.internal_user || false,
        had_registration: !!registrant,
        had_participated: hadParticipated
    };
};

// Build final result array
const result = [];

// Add all participants (with or without registration)
aggregated.forEach((data) => {
    result.push(buildResult(data.registrant, data));
});

// Add registrants who didn't participate
registrants.forEach(reg => {
    if (!participatedRegistrantIds.has(reg.id)) {
        result.push(buildResult(reg, null));
    }
});

return {
    participants: result,
    total_count: result.length,
    participated_count: aggregated.size,
    no_show_count: result.length - aggregated.size
};
